// 同一正式作者情景验证明确接续、私产守恒、冷计划终态及末端整World回滚；不代GUI验收。
#define ADULT_ADOPTION_HELPERS_ONLY
#include "adult_adoption_live_probe.cpp"
#include "resident/domains/family/voluntary_succession.hpp"
namespace {
const StableId predecessor="society::actor.city_steward",successor="society::actor.apprentice",grain="society::item.millet";
// 所有参数来自有限原生页，不由探针另造同意或收养事实。
V succession_page(ResidentReplaySession& session){return query(session,"voluntary_succession_page",boundary::obj({{"page",V{Integer{0}}}}));}
// 个人账户沿原人物头解析，不能把组织工资或生产容器计入继承。
Integer private_money(const V& state,const StableId& actor){return boundary::get_int(field(field(state,"wallets"),text(field(field(state,"actors"),actor.c_str()),"wallet_id").c_str()),"balance","wallet");}
// 只汇总当事人自己所有的随身指定品类，保留他人货物与预留状态。
Integer private_grain(const V& state,const StableId& actor){Integer total=0;const auto& bag=field(field(state,"inventories"),text(field(field(state,"actors"),actor.c_str()),"inventory_id").c_str());for(const auto& lot:boundary::array(field(bag,"lots"),"lots"))if(text(lot,"item_id")==grain&&text(field(lot,"owner"),"kind")=="actor"&&text(field(lot,"owner"),"id")==actor)total+=boundary::get_int(lot,"quantity","lot");return total;}
// 冷载保存全部字节；标题选择须保新Family位而不是退回普通收养。
std::unique_ptr<ResidentReplaySession> cold_same(ResidentReplaySession& live,const V& catalog,const StableId& who){const auto bank=need(live.checkpoint(),"source checkpoint");auto cold=create_resident_replay_session();const auto selection=need(cold->inspect_checkpoint_selection(bank),"new Family title selection");check(text(selection,"scenario_id")=="succession::scenario.qingchuan_voluntary_succession"&&text(selection,"player_actor_id")==who,"title lost succession actor/profile");need(cold->initialize_checkpoint(catalog,bank),"exact original plan cold restore");check(bank==need(cold->checkpoint(),"cold byte identity"),"cold changed complete world bytes");return cold;}
// 实际未完成计划的独立取消分支保留所有钱货，冷载后增加终态也可再次保存。
void cancel_branch(ResidentReplaySession& accepted,const V& catalog,const StableId& plan_id,const std::filesystem::path& output){auto cancelled=cold_same(accepted,catalog,predecessor);const auto before=export_state(*cancelled);submit(*cancelled,"family_cancel_succession",boundary::obj({{"plan_id",V{plan_id}}}));const auto after=export_state(*cancelled);for(const auto* key:{"actors","wallets","inventories","roles"})check(compare_boundary(field(before,key),field(after,key)).exact(),StableId("cancellation changed ")+key);auto cold=cold_same(*cancelled,catalog,predecessor);check(text(boundary::array(field(succession_page(*cold),"plans"),"plans").front(),"state")=="cancelled","cold cancellation lost conclusion");save_bank(*cold,output,"cancelled");}
// 新款坏来源保原world_id正向对照；有效封装摘要不等于合法同意或允许扩大赠与。
void reject_bad_plan(ResidentReplaySession& accepted,const V& catalog){const auto original=need(accepted.checkpoint(),"valid consent source bank");auto prepared=prepared_for(accepted,catalog);auto envelope=need(decode_checkpoint(original,prepared->identity,need(checkpoint_domains_from_identity({{},0,0,prepared->identity}),"new selected domains")),"decode selected consent bank");auto state=export_state(accepted);auto baseline=need(decode_world_seed(state,*prepared),"decode unchanged consent JSON");baseline.common.identity.world_id=envelope.identity.world_id;ResidentWorld valid;need(valid.install(prepared,std::move(baseline)),"unchanged consent source installs");V* agreement=nullptr;for(auto& row:*state.find("facts")->as<V::Dict>())if(row.second.find("kind")&&text(row.second,"kind")=="family_succession_consent")agreement=row.second.find("agreement");check(agreement,"actual accepted source missing");agreement->find("personal")->find("money")->data=Integer{11};auto bad=need(decode_world_seed(state,*prepared),"decode larger personal amount");bad.common.identity.world_id=envelope.identity.world_id;ResidentWorld enlarged;auto refusal=enlarged.install(prepared,std::move(bad));check(!refusal.ok&&refusal.error.original.code=="SuccessionConsentBindingMismatch","cold source silently expanded accepted money: "+refusal.error.original.code);
    bool changed=false;for(auto& section:envelope.sections)if(section.domain=="family"){check(section.codec_version==13,"selected adult+voluntary profile requires Family13");const StableId key="relation_fact_id";auto found=std::find_end(section.payload.begin(),section.payload.end(),key.begin(),key.end());check(found!=section.payload.end(),"new source field order absent");std::fill_n(found,key.size(),static_cast<std::uint8_t>('x'));changed=true;}check(changed,"new Family section absent");const auto damaged=need(encode_checkpoint(envelope),"valid outer digest with broken new field order");check(!accepted.restore(damaged).ok&&original==need(accepted.checkpoint(),"failed restore retains original world"),"bad plan restored or replaced live world");auto fresh=create_resident_replay_session();check(!fresh->initialize_checkpoint(catalog,damaged).ok,"fresh reader accepted damaged new source");}
// 同一真实闭会计划仅把实例计数移到末端；分项交割后结果ID失败必须整World不变。
void late_completion(ResidentReplaySession& closed,const V& catalog,const V& params){const auto original=need(closed.checkpoint(),"original closed plan bank");const auto prepared=prepared_for(closed,catalog);const auto bank=need(decode_checkpoint(original,prepared->identity,need(checkpoint_domains_from_identity({{},0,0,prepared->identity}),"closed domain selection")),"decode closed envelope");auto state=export_state(closed);state.find("next_instance_id")->data=std::numeric_limits<Integer>::max()-2;auto source=need(decode_world_seed(state,*prepared),"decode exhausted closed plan");source.common.identity.world_id=bank.identity.world_id;ResidentWorld isolated;need(isolated.install(prepared,std::move(source)),"fully install exhausted derivative");const auto identity=need(isolated.identity(),"real derivative identity");const auto context=query(closed,"command_context");CommandEnvelope command;command.world_id=identity.world_id;command.execution_epoch=identity.execution_epoch;command.expected_revision=identity.revision;command.actor_id=predecessor;command.request_seq=boundary::get_int(context,"next_request_seq","context");command.payload=std::make_shared<const CommandPayload>(need(decode_resident_command("family_continue_as",params),"decode real completion command"));const auto before=need(isolated.checkpoint(),"before late complete");need(isolated.preview(command),"late fixture passes business quote");const auto refused=isolated.submit(command);check(!refused.ok&&refused.error.original.code=="InstanceIdOverflow","completion failed before expected final receipt ID: "+refused.error.original.code);check(before==need(isolated.checkpoint(),"after late completion"),"late completion published partial resources or control");
    auto seed=need(decode_world_seed(state,*prepared),"same direct candidate");seed.common.identity=identity;WorldBundle candidate(prepared,std::move(seed));need(candidate.validate(),"same candidate fully valid");auto interaction=candidate.services.interaction_access();auto access=candidate.services.family_access(interaction);auto typed=need(decode_family_command("family_continue_as",params),"typed same command");auto quote=need(preview_family(candidate.common,candidate.family,*prepared->family,*prepared->common,candidate.estate,*prepared->estate,access,predecessor,typed),"direct actual quote");need(apply_family_instant(candidate.common,candidate.family,candidate.estate,*prepared->family,*prepared->common,*prepared->estate,access,predecessor,typed,quote),"actual resources/control precede receipt refusal");check(candidate.common.state().metadata.player_actor_id==successor,"direct candidate never changed control");check(!candidate.common.next_id("result").ok,"receipt ID did not fail after full direct effect");check(original==need(closed.checkpoint(),"natural source remains untouched"),"late derivative touched source world");}
}
int main(int argc,char** argv){std::filesystem::path output;try{
    check(argc==4,"Usage: voluntary_succession_live_probe INSTALLED_CATALOG NATIVE_REQUEST FRESH_OUTPUT");output=argv[3];check(!std::filesystem::exists(output),"fresh output required");std::filesystem::create_directories(output);const auto catalog=read(argv[1]),request=read(argv[2]);check(text(request,"scenario_id")=="succession::scenario.qingchuan_voluntary_succession","explicit new author scene required");auto live=create_resident_replay_session();need(live->initialize_native(catalog,request),"install actual voluntary succession author");check(text(query(*live,"command_context"),"actor_id")==predecessor,"wrong original player");const auto initial=export_state(*live);check(private_money(initial,predecessor)==80&&private_grain(initial,predecessor)==3,"author-selected private assets missing");check(boundary::get_int(succession_page(*live),"request_count","page")==0,"unreached consent leaked");
    submit(*live,"talk",boundary::obj({{"role_id",V{"adultfamily::role.adoption_request"}}}));const auto adoption=query(*live,"adult_adoption_requests",boundary::obj({{"page",V{Integer{0}}}}));const auto& requests=boundary::array(field(adoption,"requests"),"requests");check(requests.size()==1&&boundary::get_bool(requests.front(),"eligible","request"),"same real adult not adoptable");submit(*live,"family_adopt_existing",field(requests.front(),"params"));submit(*live,"end_interaction",boundary::obj({}));submit(*live,"talk",boundary::obj({{"role_id",V{"succession::role.succession_consent"}}}));auto page=succession_page(*live);const auto& sources=boundary::array(field(page,"requests"),"requests");check(sources.size()==1,"real consent node not reached");const auto operation=field(sources.front(),"accept_action");check(boundary::get_bool(operation,"available","accept action"),"author consent not currently available");readonly_quote(*live,operation);submit_action(*live,operation);const auto accepted=export_state(*live);for(const auto* key:{"actors","wallets","inventories","roles"})check(compare_boundary(field(initial,key),field(accepted,key)).exact(),StableId("acceptance changed ")+key);page=succession_page(*live);const auto& plans=boundary::array(field(page,"plans"),"plans");check(plans.size()==1&&text(plans.front(),"state")=="accepted","explicit consent did not form exactly one pending plan");const auto plan_id=text(plans.front(),"plan_id");save_bank(*live,output,"accepted");cancel_branch(*live,catalog,plan_id,output);reject_bad_plan(*live,catalog);
    live=cold_same(*live,catalog,predecessor);submit(*live,"end_interaction",boundary::obj({}));const auto before=export_state(*live);auto params=boundary::obj({{"plan_id",V{plan_id}}});save_bank(*live,output,"closed");late_completion(*live,catalog,params);auto command=envelope(*live,"family_continue_as",params);auto result=call(*live,LiveOperationKind::command,command,"explicit final completion");const auto completed=need(live->checkpoint(),"completed full bank");auto replay=call(*live,LiveOperationKind::command,command,"same completion replay");check(compare_boundary(result,replay).exact()&&completed==need(live->checkpoint(),"same completion bank"),"same receipt duplicated control or gift");const auto after=export_state(*live);check(private_money(after,predecessor)==private_money(before,predecessor)-10&&private_money(after,successor)==private_money(before,successor)+10,"selected cash not conserved");check(private_grain(after,predecessor)==private_grain(before,predecessor)-2&&private_grain(after,successor)==private_grain(before,successor)+2,"selected goods not conserved");for(const auto* key:{"actors","roles","social","growth","organization","estate"})if(before.find(key))check(compare_boundary(field(before,key),field(after,key)).exact(),StableId("completion overwrote original ")+key);check(text(query(*live,"command_context"),"actor_id")==successor,"control did not move to actual existing successor");save_bank(*live,output,"completed");auto cold=cold_same(*live,catalog,successor);check(text(boundary::array(field(succession_page(*cold),"plans"),"plans").front(),"state")=="completed","cold completion lost same accepted source");save((output/"result.json").c_str(),true);std::cout<<"VOLUNTARY_SUCCESSION_LIVE "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& error){if(!output.empty()&&std::filesystem::exists(output))try{save((output/"failure.json").c_str(),false,error.what());}catch(...){}std::cerr<<"VOLUNTARY_SUCCESSION_LIVE FAIL "<<error.what()<<'\n';return 1;}}
